"""Reusable conversions for legacy Meridian CRM storage conventions."""

from datetime import date
from decimal import Decimal, ROUND_HALF_UP


_LEGACY_NULL_DATE = "00000000"


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO format, mapping sentinels to None."""
    if yyyymmdd is None or yyyymmdd in ("", _LEGACY_NULL_DATE):
        return None

    if len(yyyymmdd) != 8 or not yyyymmdd.isdigit():
        raise ValueError(f"invalid legacy date: {yyyymmdd!r}")

    parsed = date(
        int(yyyymmdd[0:4]),
        int(yyyymmdd[4:6]),
        int(yyyymmdd[6:8]),
    )
    return parsed.isoformat()


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to the legacy YYYYMMDD representation."""
    if iso is None or iso == "":
        return _LEGACY_NULL_DATE

    if (
        len(iso) != 10
        or iso[4] != "-"
        or iso[7] != "-"
        or not (iso[0:4] + iso[5:7] + iso[8:10]).isdigit()
    ):
        raise ValueError(f"invalid ISO date: {iso!r}")

    parsed = date(int(iso[0:4]), int(iso[5:7]), int(iso[8:10]))
    return f"{parsed.year:04d}{parsed.month:02d}{parsed.day:02d}"


def yn(char: str | None) -> bool:
    """Convert a legacy Y/N flag to bool; N, blank, and None are false."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a decimal legacy amount to currency minor units, half-up."""
    if amount is None or (isinstance(amount, str) and amount.strip() == ""):
        return 0

    currency_code = "USD" if currency is None or currency.strip() == "" else currency
    exponent = 0 if currency_code.strip().upper() == "JPY" else 2

    decimal_amount = Decimal(str(amount))
    scaled = decimal_amount * (Decimal(10) ** exponent)
    return int(scaled.to_integral_value(rounding=ROUND_HALF_UP))
